#include <cwctype>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::wctype_t alpha = std::wctype("alpha");
    assert(alpha && std::iswctype(L'A', alpha));
    std::wctrans_t lower = std::wctrans("tolower");
    assert(lower && std::towctrans(L'A', lower) == L'a');
}
